// fetch-decode-execute + Actor cooperative scheduling

import { Op, Chunk, FuncInfo } from "./compiler";
import * as crypto from "crypto";

// ============================================================
// Value (SPEC_02 Q3)
// ============================================================

export type Value =
  | { tag: "i32"; val: number }
  | { tag: "f64"; val: number }
  | { tag: "str"; val: string }
  | { tag: "bool"; val: boolean }
  | { tag: "arr"; val: Value[] }
  | { tag: "struct"; fields: Map<string, Value> }
  | { tag: "ok"; val: Value }
  | { tag: "err"; val: Value }
  | { tag: "some"; val: Value }
  | { tag: "none" }
  | { tag: "chan"; id: number }
  | { tag: "void" };

// ============================================================
// CallFrame (SPEC_02 Q5)
// ============================================================

type CallFrame = {
  returnAddr: number;
  baseSlot: number;
  locals: Value[];
};

// ============================================================
// Channel
// ============================================================

type Channel = {
  id: number;
  buffer: Value[];
  waitingRecv: number[]; // actor ids waiting to recv
};

// ============================================================
// Actor (SPEC_02 Q7)
// ============================================================

type Actor = {
  id: number;
  ip: number;
  stack: Value[];
  frames: CallFrame[];
  state: "running" | "waiting" | "done";
  waitingChan: number | null;
};

// ============================================================
// VM
// ============================================================

export class VM {
  private chunk!: Chunk;
  private actors: Actor[] = [];
  private channels: Channel[] = [];
  private globals: Map<string, Value> = new Map();
  private output: string[] = [];
  private instructionCount: number = 0;
  private maxInstructions: number = 1_000_000;

  run(chunk: Chunk): { output: string[]; error: string | null } {
    this.chunk = chunk;
    this.output = [];
    this.instructionCount = 0;

    // main actor
    this.actors = [{
      id: 0,
      ip: 0,
      stack: [],
      frames: [{ returnAddr: -1, baseSlot: 0, locals: [] }],
      state: "running",
      waitingChan: null,
    }];

    try {
      this.schedule();
      return { output: this.output, error: null };
    } catch (e: any) {
      return { output: this.output, error: e.message || String(e) };
    }
  }

  // ============================================================
  // Scheduler — round-robin (SPEC_02 Q7)
  // ============================================================

  private schedule(): void {
    const SLICE = 1000;
    let current = 0;

